import{_ as i,o as a,c as s,ao as t}from"./chunks/framework.Dgd2CJDb.js";const k=JSON.parse('{"title":"Memory & ownership","description":"","frontmatter":{},"headers":[],"relativePath":"implementation/ownership.md","filePath":"implementation/ownership.md","lastUpdated":null}'),r={name:"implementation/ownership.md"};function n(o,e,l,h,d,p){return a(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="Memory-and-ownership" tabindex="-1">Memory &amp; ownership <a class="header-anchor" href="#Memory-and-ownership" aria-label="Permalink to &quot;Memory &amp; ownership {#Memory-and-ownership}&quot;">​</a></h1><p>VTK is reference-counted; Julia is garbage-collected. The bridge between them is the subtlest part of VTK.jl, and the one with a genuine landmine discovered during development.</p><h2 id="The-model" tabindex="-1">The model <a class="header-anchor" href="#The-model" aria-label="Permalink to &quot;The model {#The-model}&quot;">​</a></h2><ul><li><p><strong>Factories and outputs</strong> (<code>UnstructuredGrid()</code>, <code>clip(...)</code>, <code>read_vtu(...)</code>) return <code>vtkSmartPointer{T}</code> registered as a CxxWrap smart pointer. Julia holds one strong reference; when the Julia object is collected, the finalizer calls <code>UnRegister</code>, and VTK frees the object when its count hits zero. GC-stress tests (thousands of allocations with survivors) verify this.</p></li><li><p><strong>Getters are borrowed.</strong> <code>point_data(grid)</code>, <code>points(grid)</code>, <code>field_array_raw(...)</code> return <code>take_ref</code>&#39;d smart pointers: an extra <code>Register</code> balanced by the Julia finalizer&#39;s <code>UnRegister</code>. The underlying storage stays owned by the grid.</p></li><li><p><strong>Views own through the wrapper.</strong> <code>data(x)</code> returns a <code>VTKDataArray</code> that <em>holds</em> the smart pointer as a field; <code>raw_data(x)</code> returns a flat view derived from it (<code>vec(wrapper)</code>). The derivation chain — <code>ReshapedArray → VTKDataArray → SmartPointer</code> — keeps the C++ object alive <strong>structurally</strong>, with no finalizers on views:</p></li></ul><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">da </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> VTK</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">data_array</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Float64, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">VTK</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">resize!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(da, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">v </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> VTK</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">raw_data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(da</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">obj)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">da </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> nothing</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; GC</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">gc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># the ONLY owner reference is gone…</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">v[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]                    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># …and v is still valid: it owns a share</span></span></code></pre></div><p>This is the &quot;wrapper-owns-everything&quot; design. Releasing the C++ object happens when the <em>last</em> wrapper/view chain is collected — through CxxWrap&#39;s standard <code>SmartPointer</code> finalizer, i.e. the same baseline mechanism the package has always relied on.</p><h2 id="Why-not-attach-owner-capturing-finalizers-to-views-directly?" tabindex="-1">⚠️ Why not attach owner-capturing finalizers to views directly? <a class="header-anchor" href="#Why-not-attach-owner-capturing-finalizers-to-views-directly?" aria-label="Permalink to &quot;⚠️ Why not attach owner-capturing finalizers to views directly? {#Why-not-attach-owner-capturing-finalizers-to-views-directly?}&quot;">​</a></h2><p>An earlier experiment did exactly that (<code>finalizer(_ -&gt; da, view)</code>) to save the wrapper indirection. <strong>It corrupts concurrent pipelines.</strong> Measured on this codebase: ~25% of test runs failed with heisenbug garbage reads once C++ objects started dying on Julia&#39;s GC finalizer threads while the main thread was inside VTK algorithms; the failures vanished under <code>--gcthreads=1</code> and were absent with no-op finalizers — proving the trigger was the <em>owner capture</em>, not the extra allocation.</p><p>The rule that emerged: <strong>C++ VTK objects must not be destroyed from GC finalizer threads beyond the baseline rate.</strong> The wrapper-owns design respects it: views never carry finalizers, the object graph keeps owners alive, and the only finalizer-driven releases are the standard smart-pointer ones (factories, outputs, wrappers) — empirically stable across thousands of test runs. Do not &quot;optimize&quot; the indirection away.</p><p>(The full forensics — bisection, the no-op-finalizer control, the gcthreads experiment — are in the git history of <code>30a1ea2</code> and recorded in <code>STATUS.md</code> §4.1/§5.)</p><h2 id="Resize-semantics" tabindex="-1">Resize semantics <a class="header-anchor" href="#Resize-semantics" aria-label="Permalink to &quot;Resize semantics {#Resize-semantics}&quot;">​</a></h2><p><code>resize!</code> calls VTK&#39;s <code>SetNumberOfTuples</code>, which may <strong>reallocate</strong>:</p><ol><li><p>previously obtained views of the same array dangle — do not use them;</p></li><li><p>the grown region is <strong>not zero-initialized</strong> (VTK hands you allocator leftovers) — initialize before whole-array reductions.</p></li></ol><p>Both are VTK behaviors, faithfully surfaced.</p><h2 id="Practical-checklist" tabindex="-1">Practical checklist <a class="header-anchor" href="#Practical-checklist" aria-label="Permalink to &quot;Practical checklist {#Practical-checklist}&quot;">​</a></h2><ul><li><p><code>data</code>/<code>raw_data</code> results keep the storage alive — dropping the owner is safe.</p></li><li><p>Views obtained before <code>resize!</code> are dead afterwards.</p></li><li><p>Don&#39;t reduce over freshly-grown storage before writing it.</p></li><li><p>Don&#39;t attach your own finalizers to VTK objects or views.</p></li></ul>`,16)])])}const g=i(r,[["render",n]]);export{k as __pageData,g as default};
